<?php
declare(strict_types=1);require_once __DIR__.'/SearchService.php';require_once __DIR__.'/HttpClient.php';
final class PhpTools {
    public function __construct(private readonly array $config,private readonly WorkspaceService $workspace){}
    private function fn(string $name,string $description,array $properties=[],array $required=[]):array{return ['type'=>'function','function'=>['name'=>$name,'description'=>$description,'parameters'=>['type'=>'object','properties'=>(object)$properties,'required'=>$required]]];}
    public function definitions():array{$path=['type'=>'string','description'=>'Caminho relativo à workspace'];return [$this->fn('pesquisar_arquivos','Pesquisa conteúdo e nomes recursivamente com filtros.',['termo'=>['type'=>'string'],'nome'=>['type'=>'string'],'caminho'=>$path,'extensao'=>['type'=>'string'],'modo'=>['type'=>'string','enum'=>['content','name','both']],'limite'=>['type'=>'integer','minimum'=>1,'maximum'=>200]]),$this->fn('analisar_projeto','Analisa a estrutura de um projeto sem executar código.',['caminho'=>$path],['caminho']),$this->fn('pesquisar_web_gratis','Pesquisa resultados públicos usando DuckDuckGo HTML, sem chave paga.',['pergunta'=>['type'=>'string']],['pergunta']),$this->fn('get_datetime','Retorna a data e hora atuais do servidor local.'),$this->fn('run_javascript','Calculadora compatível com a ferramenta do Bonsai. Aceita somente expressões aritméticas; não executa JavaScript arbitrário.',['code'=>['type'=>'string'],'timeout_ms'=>['type'=>'integer','minimum'=>1,'maximum'=>10000]],['code'])];}
    public function execute(string $name,array $args):array{return match($name){'pesquisar_arquivos'=>(new SearchService($this->workspace,$this->config))->search($args),'analisar_projeto'=>$this->analyzeProject($args),'pesquisar_web_gratis'=>$this->searchWeb($args),'get_datetime'=>$this->dateTime(),'run_javascript'=>$this->calculator((string)($args['code']??'')),default=>throw new InvalidArgumentException('Ferramenta PHP desconhecida: '.$name)};}
    private function dateTime():array{$now=new DateTimeImmutable('now');return ['iso8601'=>$now->format(DateTimeInterface::ATOM),'data'=>$now->format('d/m/Y'),'hora'=>$now->format('H:i:s'),'fuso'=>$now->getTimezone()->getName()];}
    private function calculator(string $code):array{$expr=trim($code);if($expr===''||strlen($expr)>200||!preg_match('/^[0-9+\-*\/().%\s]+$/',$expr))throw new InvalidArgumentException('run_javascript aceita apenas uma expressão aritmética simples.');$tokens=preg_split('/\s*([+\-*\/()%])\s*/',$expr,-1,PREG_SPLIT_DELIM_CAPTURE|PREG_SPLIT_NO_EMPTY);$values=[];$ops=[];$prec=['+'=>1,'-'=>1,'*'=>2,'/'=>2,'%'=>2];$apply=function()use(&$values,&$ops){$op=array_pop($ops);$b=array_pop($values);$a=array_pop($values);if($a===null||$b===null)throw new InvalidArgumentException('Expressão aritmética inválida.');if($op==='+')$values[]=$a+$b;elseif($op==='-')$values[]=$a-$b;elseif($op==='*')$values[]=$a*$b;elseif($op==='/'){if($b==0)throw new InvalidArgumentException('Divisão por zero.');$values[]=$a/$b;}else{if((int)$b==0)throw new InvalidArgumentException('Módulo por zero.');$values[]=(int)$a%(int)$b;}};foreach($tokens as $token){if(is_numeric($token)){$values[]=(float)$token;continue;}if($token==='('){$ops[]=$token;continue;}if($token===')'){while($ops&&end($ops)!=='(')$apply();if(!$ops)throw new InvalidArgumentException('Parênteses inválidos.');array_pop($ops);continue;}if(isset($prec[$token])){while($ops&&end($ops)!=='('&&$prec[end($ops)]>=$prec[$token])$apply();$ops[]=$token;continue;}throw new InvalidArgumentException('Expressão inválida.');}while($ops){if(end($ops)==='(')throw new InvalidArgumentException('Parênteses inválidos.');$apply();}if(count($values)!==1)throw new InvalidArgumentException('Expressão aritmética inválida.');$result=$values[0];return ['code'=>$expr,'resultado'=>fmod($result,1.0)===0.0?(int)$result:$result,'executou_javascript'=>false,'modo'=>'calculadora segura'];}
    private function analyzeProject(array $a):array{$root=$this->workspace->safe((string)($a['caminho']??'.'),true);if(!is_dir($root))throw new RuntimeException('A pasta do projeto não existe.');$files=[];$types=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($it as $file){if(count($files)>=200||!$file->isFile())continue;$rel=substr($file->getPathname(),strlen($this->workspace->root())+1);try{$this->workspace->safe($rel,true);}catch(Throwable){continue;}$ext=strtolower(pathinfo($rel,PATHINFO_EXTENSION));$files[]=$rel;if($ext!=='')$types[$ext]=($types[$ext]??0)+1;}return ['pasta'=>(string)($a['caminho']??'.'),'arquivos'=>$files,'extensoes'=>$types,'executou_codigo'=>false,'limitado'=>count($files)>=200];}
    private function searchWeb(array $a):array{$q=trim((string)($a['pergunta']??''));if($q===''||strlen($q)>300)throw new InvalidArgumentException('Pergunta vazia ou longa demais.');$url='https://html.duckduckgo.com/html/?q='.rawurlencode($q);$html=HttpClient::text($url,['User-Agent: ZystemWorkSpace/1.0'],15);preg_match_all('/<a[^>]+class="result__a"[^>]+href="([^"]+)"[^>]*>(.*?)<\/a>/is',$html,$m);$out=[];foreach(array_slice($m[1]??[],0,5) as $i=>$url)$out[]=['titulo'=>trim(strip_tags($m[2][$i]??'')),'url'=>html_entity_decode($url,ENT_QUOTES|ENT_HTML5,'UTF-8')];return ['pergunta'=>$q,'resultados'=>$out,'fonte'=>'DuckDuckGo HTML','custo'=>'gratuito'];}
}
?>
